"""USAR suite bundles: one self-contained benchmark suite per split, regenerated byte for byte from its manifest."""

import math
import shutil
from pathlib import Path

import pytest
import yaml
from arena_simulation_setup.generative.usar import bundle, cli
from arena_simulation_setup.generative.usar.manifest import Manifest
from arena_simulation_setup.tree.World import WorldView
from arena_simulation_setup.tree.World.Scenario import ScenarioView

SPLIT: dict[str, object] = {"name": "unit", "seed": 3, "spots_per_world": 2, "worlds": [{"world": {"rows": 3, "cols": 3, "loops": 1}, "world_variants": 2, "corners": [0, 1], "test_worlds": 1}]}


def with_group(**overrides: object) -> dict[str, object]:
    groups = SPLIT["worlds"]
    assert isinstance(groups, list)
    return {**SPLIT, "worlds": [{**groups[0], **overrides}]}


def written(root: Path, data: dict[str, object] = SPLIT, name: str = "unit") -> list[Path]:
    manifest = Manifest.model_validate(data)
    return bundle.write(manifest, cli.run(manifest), root, name)


def tree(path: Path) -> dict[str, bytes]:
    return {p.relative_to(path).as_posix(): p.read_bytes() for p in sorted(path.rglob("*")) if p.is_file()}


def stages(path: Path) -> list[dict]:
    return yaml.safe_load((path / "suite.yaml").read_text())["stages"]


def test_two_runs_into_different_roots_write_the_same_bytes(tmp_path: Path):
    first, second = written(tmp_path / "a"), written(tmp_path / "b")
    assert [path.name for path in first] == ["unit_test", "unit_tune"]
    assert [tree(path) for path in first] == [tree(path) for path in second]
    assert all(tree(path) for path in first)


def test_the_index_records_the_checksum_of_its_bundle(tmp_path: Path):
    for path in written(tmp_path):
        index = yaml.safe_load((path / f"{path.name}.index.yaml").read_text())
        assert index["checksum"] == bundle.checksum(path)
        assert len(index["checksum"]) == 64
        assert (index["manifest"], index["seed"], index["split"]) == ("unit", 3, path.name.removeprefix("unit_"))
        assert index["worlds"] == sorted(d.name for d in (path / "worlds").iterdir())
        assert index["stages"] == len(stages(path)) == len(index["tasks"])


def test_the_checksum_changes_with_any_file_but_the_index(tmp_path: Path):
    path = written(tmp_path)[0]
    before = bundle.checksum(path)
    (path / f"{path.name}.index.yaml").write_text("x")
    assert bundle.checksum(path) == before
    (path / "README.md").write_text("x")
    assert bundle.checksum(path) != before


def test_every_stage_carries_the_fixed_search_settings_and_names_a_bundled_scenario(tmp_path: Path):
    for path in written(tmp_path):
        assert stages(path)
        for stage in stages(path):
            assert set(stage) == {"name", "map", "robot", "modes", "episodes", "timeout", "config"}
            assert (stage["robot"], stage["episodes"], stage["timeout"]) == ("auto", 3, "300s")
            assert stage["modes"] == {"robots": "search", "obstacles": "scenario"}
            assert stage["config"]["search"] == {"radius": 1.0, "line_of_sight": True, "dwell_s": 0.0}
            assert stage["name"] == f"{stage['map']}__{stage['config']['scenario']['file']}"
            assert (path / "worlds" / stage["map"] / "scenarios" / stage["config"]["scenario"]["file"] / "scenario.yaml").is_file()
        assert len({stage["name"] for stage in stages(path)}) == len(stages(path))


def test_the_suite_file_repeats_its_settings_in_plain_yaml(tmp_path: Path):
    for path in written(tmp_path):
        text = (path / "suite.yaml").read_text()
        assert "&" not in text and "*" not in text


def test_each_bundle_holds_only_the_worlds_and_stages_of_its_split(tmp_path: Path):
    bundles = written(tmp_path)
    maps = [{stage["map"] for stage in stages(path)} for path in bundles]
    assert maps[0] and maps[1] and not maps[0] & maps[1]
    assert [{d.name for d in (path / "worlds").iterdir()} for path in bundles] == maps


def test_every_task_of_a_bundle_is_a_valid_search_task(tmp_path: Path):
    for path in written(tmp_path):
        for stage in stages(path):
            name = stage["config"]["scenario"]["file"]
            scenario_dir = path / "worlds" / stage["map"] / "scenarios" / name
            scenario = ScenarioView(scenario_dir).load()
            assert [human.name for human in scenario.humans] == ["caller"]
            assert [robot.phases for robot in scenario.robots] == [[]]
            assert [sound.name for sound in scenario.sounds] == ["call"]
            assert len(yaml.safe_load((scenario_dir / "scenario.yaml").read_text())["timeline"]) == 2
            design = yaml.safe_load((scenario_dir / "provenance.yaml").read_text())["design"]
            assert f"__c{design['corners']}__" in name
            assert math.dist(design["robot_start"][:2], design["person"]) >= 3.0


def test_a_copied_bundle_loads_from_its_new_place_and_names_no_absolute_path(tmp_path: Path):
    original = written(tmp_path / "made")[0]
    copy = tmp_path / "elsewhere" / original.name
    shutil.copytree(original, copy)
    shutil.rmtree(tmp_path / "made")
    for stage in stages(copy):
        world = WorldView(copy / "worlds" / stage["map"])
        assert world.load().levels
        assert ScenarioView(world.path / "scenarios" / stage["config"]["scenario"]["file"]).load().humans
    assert not [name for name, content in tree(copy).items() if str(tmp_path).encode() in content]


def test_an_empty_split_writes_no_bundle(tmp_path: Path):
    assert [path.name for path in written(tmp_path, with_group(test_worlds=2))] == ["unit_test"]
    assert [path.name for path in tmp_path.iterdir()] == ["unit_test"]


def test_a_rejected_spot_writes_nothing(tmp_path: Path):
    with pytest.raises(ValueError, match="rejected"):
        written(tmp_path, with_group(corners=[9]))
    assert not any(tmp_path.iterdir())


def test_an_existing_bundle_is_replaced_and_its_neighbour_kept(tmp_path: Path):
    stale = tmp_path / "unit_test" / "worlds" / "stale" / "x"
    keep = tmp_path / "other" / "keep"
    for path in (stale, keep):
        path.parent.mkdir(parents=True)
        path.write_text("old")
    written(tmp_path)
    assert not stale.parent.exists()
    assert keep.read_text() == "old"


def test_the_readme_lists_one_row_per_world_with_its_placed_axes(tmp_path: Path):
    for path in written(tmp_path):
        rows = [line for line in (path / "README.md").read_text().splitlines() if line.startswith("| usar_rooms_")]
        assert sorted(row.split("|")[1].strip() for row in rows) == sorted(d.name for d in (path / "worlds").iterdir())
        for row in rows:
            cells = [cell.strip() for cell in row.strip("|").split("|")]
            assert cells[1:] == ["0, 1", "weak, loud", "random", "3 x 3 = 9"]


def test_a_dry_run_report_carries_the_built_worlds_and_writes_nothing(tmp_path: Path):
    report = cli.run(Manifest.model_validate(SPLIT), out=tmp_path)
    assert set(report.built) == {outcome.task.world_key for outcome in report.outcomes if outcome.reason is None}
    assert all(any(name.endswith("scenario.yaml") for name in built.files) for built in report.built.values())
    assert not any(tmp_path.iterdir())
